import {
  Component,
  ComponentInterface,
  h,
  Prop,
  State,
  Watch,
  Method,
  Host,
  Element,
  EventEmitter,
  Event,
} from '@stencil/core';
import { t } from '@src/shared/i18n';
import { Slot, AllSlots, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking, sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { ModalCancelReason, ModalSize } from './types';
import { commonMessages } from '@fe-infra/keystone-locales';
import { asObject } from '@src/shared/type-utils';
import { formatCSSLength } from '@src/shared/dom';
import { createOpenCloseMotion } from '@src/shared/animation';
import { KsIconClose } from '@fe-infra/keystone-icons-stencil';

const prefix = 'modal';

/**
 * @slot title - Allows customization of the modal's title content. If not provided, the `title` prop is used.
 * @slot description - Allows customization of the description text displayed below the title in the header. If not provided, the `description` prop is used.
 * @slot body - Allows customization of the main content area of the modal.
 * @slot default - Provides the main modal body content inside the built-in content container when the `body` slot is not provided.
 * @slot footer - Allows customization of the modal's footer content. If not provided, default buttons are rendered based on props.
 * @slot footerPrepend - Allows customization of the prepend area in the footer without replacing the confirm and cancel buttons.
 * @slot cancelText - Allows customization of the cancel button's content. If not provided, the `cancelText` prop or a default localized string is used.
 * @slot confirmText - Allows customization of the confirm button's content. If not provided, the `confirmText` prop or a default localized string is used.
 * @slot closeIcon - Allows customization of the close button (typically an "X" icon) in the header.
 * @part backdrop - The backdrop element.
 * @part base - The base container of the component.
 * @part wrapper - The wrapper element that controls the modal size and width.
 * @part header - The header container.
 * @part closeIcon - The close icon button.
 * @part content - The content container.
 * @part footer - The footer container.
 * @part cancelButton - The built-in cancel button.
 * @part confirmButton - The built-in confirm button.
 */
@Component({
  tag: 'ks-modal',
  styleUrls: ['index.scss'],
  shadow: true,
})
export class KsModal implements ComponentInterface {
  static vModel = { prop: 'open', event: 'ksOpenChange' };
  @Element() el!: HTMLKsModalElement;
  private overlayRef?: HTMLElement;
  private wrapperRef?: HTMLElement;
  private openAnimation = createOpenCloseMotion();
  private closeRequestInFlight = false;

  /** Indicates whether the dialog is open. When `true`, the dialog is shown. */
  @Prop() open?: boolean;
  /** Sets the initial open state in uncontrolled mode. */
  @Prop() defaultOpen?: boolean;
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() mergedOpen?: boolean;
  /** The size of the dialog. Can be one of the following values: `"sm"`, `"md"` or `"lg"`. */
  @Prop() size: ModalSize = 'md';
  /** The width of the dialog. Overrides the default width based on the current `size`. */
  @Prop() width?: string | number;
  /** Indicates whether the dialog has a confirm button. When `true`, a confirm button is displayed. */
  @Prop() confirmable = true;
  /** Indicates whether the dialog has a cancel button. When `true`, a cancel button is displayed. */
  @Prop() cancelable = true;
  /** Controls whether users can close the dialog. Set it to `false` to disable all close actions, or use `{ backdrop, icon, keyboard }` to control each close trigger independently. */
  @Prop() closeable?: boolean | { backdrop?: boolean; icon?: boolean; keyboard?: boolean } = true;
  /** The title text displayed at the top of the dialog. Used as fallback content for the `title` slot when the slot is not provided. */
  @Prop() title = '';

  /** The description text displayed below the title. Used as fallback content for the `description` slot when the slot is not provided. */
  @Prop() description?: string;
  /** The text displayed on the confirm button. Used as fallback content for the `confirmText` slot when the slot is not provided. */
  @Prop() confirmText?: string;
  /** The text displayed on the cancel button. Used as fallback content for the `cancelText` slot when the slot is not provided. */
  @Prop() cancelText?: string;
  /** Overrides props on the built-in action buttons and close icon. */
  @Prop() partProps?: {
    confirmButton?: { disabled?: boolean; loading?: boolean };
    cancelButton?: { disabled?: boolean; loading?: boolean };
    closeIcon?: { disabled?: boolean };
  };
  /** Indicates whether the dialog should render its footer section. When `false`, the footer is hidden. */
  @Prop() showFooter = true;
  /** Indicates whether dividers should be shown between the header, content, and footer sections. */
  @Prop() showDivider = false;

  /** Called after the dialog finishes opening. */
  @Prop() afterOpen?: () => void | Promise<void>;
  /** Called after the dialog finishes closing. */
  @Prop() afterClose?: () => void | Promise<void>;
  /** Called when the confirm button is clicked. Return `false` to keep the dialog open. */
  @Prop() onConfirm?: () => Promise<boolean> | boolean | (Promise<void> | void);
  /** Called when the dialog is dismissed by the cancel button, close icon, backdrop, or keyboard shortcut. Receives the close reason, and returning `false` keeps the dialog open. */
  // eslint-disable-next-line @stencil-community/reserved-member-names
  @Prop() onCancel?: (reason: ModalCancelReason) => Promise<boolean> | boolean | (Promise<void> | void);
  /**
   * @private DO NOT USE. This is an internal API without any public assurance. */
  @Prop() _componentDidLoadCallback?: () => void;
  /** Overrides the overlay z-index used by the dialog. */
  @Prop() zIndex?: number;

  /**
   * @private Reserved for `v-model` usage of Vue. Emits when the dialog open state changes. */
  @Event() ksOpenChange!: EventEmitter<boolean>;

  @Slot({ slotname: 'title' }) private titleSlots?: AllSlots;
  @Slot({ slotname: 'description' }) private descriptionSlots?: AllSlots;
  @Slot({ slotname: 'footer' }) private footerSlots?: AllSlots;
  @Slot({ slotname: 'footerPrepend' }) private footerPrependSlots?: AllSlots;

  @State() innerOpen = false;
  @State() confirmLoading = false;

  @Watch('mergedOpen')
  watchOpen(newValue: boolean) {
    newValue ? this._open() : this._close('programmatic');
  }

  /**
   * @private DO NOT USE. This is an internal API without any public assurance. */
  @Method()
  async _open() {
    this.closeRequestInFlight = false;
    if (this.innerOpen) {
      return;
    }
    const completed = await this.openByAnime(true);
    if (!completed || this.mergedOpen !== true) {
      return;
    }
    this.afterOpen?.();
    sendExposeTracking(this.el as HTMLElement, { eventType: 'popup' });
    sendDurationTracking(this.el as HTMLElement, { eventType: 'popup', reset: true });
  }
  /**
   * @private DO NOT USE. This is an internal API without any public assurance. */
  @Method()
  async _close(reason: 'programmatic' | 'confirmButtonClick' | ModalCancelReason) {
    if (!this.innerOpen) {
      return false;
    }
    if (reason === 'programmatic') {
      this.closeRequestInFlight = true;
      const completed = await this.openByAnime(false);
      if (!completed || this.mergedOpen !== false) {
        return false;
      }
      this.afterClose?.();
      sendDurationTracking(this.el as HTMLElement, { eventType: 'popup' });
      return true;
    }

    if (this.closeRequestInFlight) {
      return false;
    }

    this.closeRequestInFlight = true;
    try {
      if (reason === 'confirmButtonClick') {
        this.confirmLoading = true;
        if ((await this.onConfirm?.()) === false) {
          return false;
        }
      } else {
        if ((await this.onCancel?.(reason)) === false) {
          return false;
        }
      }
      this.mergedOpen = false;
      return true;
    } finally {
      if (this.mergedOpen === true) {
        this.closeRequestInFlight = false;
      }
    }
  }

  constructor() {
    registerPluginManager(this.el);
  }

  private confirmHandler = async () => {
    if (this.closeRequestInFlight) {
      return;
    }

    this.confirmLoading = true;
    try {
      await this._close('confirmButtonClick');
    } catch {
      //
    }
    this.confirmLoading = false;
    sendActionTracking(this.el as HTMLElement, { eventType: 'confirm' });
  };
  private async cancelHandler(reason: ModalCancelReason) {
    if (this.closeRequestInFlight) {
      return;
    }

    try {
      await this._close(reason);
    } catch {
      //
    }
    sendActionTracking(this.el as HTMLElement, { eventType: 'cancel' });
  }
  private handleBackdropClick = () => {
    this.closeable && asObject(this.closeable)?.backdrop !== false && this.cancelHandler('backdropClick');
  };
  private handleCloseIconClick = () => {
    this.cancelHandler('closeIconClick');
  };
  private handleCancelButtonClick = () => {
    this.cancelHandler('cancelButtonClick');
  };
  private handleRequestClose = () => {
    this.cancelHandler('keyboard');
  };

  private syncVisibility(val: boolean) {
    if (val) {
      this.overlayRef?.setAttribute('ks-open', '');
      this.innerOpen = true;

      if (this.overlayRef) {
        this.overlayRef.style.opacity = '1';
      }
      if (this.wrapperRef) {
        this.wrapperRef.style.transform = 'scale(1)';
        this.wrapperRef.style.opacity = '1';
      }
      return;
    }

    this.overlayRef?.removeAttribute('ks-open');
    this.innerOpen = false;

    if (this.overlayRef) {
      this.overlayRef.style.opacity = '0';
    }
    if (this.wrapperRef) {
      this.wrapperRef.style.transform = 'scale(0.92)';
      this.wrapperRef.style.opacity = '0';
    }
  }

  private async openByAnime(val: boolean) {
    const duration = 200;

    if (val) {
      this.overlayRef?.setAttribute('ks-open', '');
      this.innerOpen = true;
    }

    if (this.overlayRef) {
      this.overlayRef.style.opacity = val ? '0' : '1';
    }
    if (this.wrapperRef) {
      this.wrapperRef.style.transform = `scale(${val ? '0.92' : '1'})`;
      this.wrapperRef.style.opacity = val ? '0' : '1';
    }

    const completed = await this.openAnimation.run({
      elements: [this.el, this.overlayRef, this.wrapperRef],
      items: [
        {
          element: this.overlayRef,
          keyframes: [{ opacity: val ? '0' : '1' }, { opacity: val ? '1' : '0' }],
          duration,
        },
        {
          element: this.wrapperRef,
          keyframes: [
            { transform: `scale(${val ? '0.92' : '1'})`, opacity: val ? '0' : '1' },
            { transform: `scale(${val ? '1' : '0.92'})`, opacity: val ? '1' : '0' },
          ],
          duration,
        },
      ],
      fallback: () => this.syncVisibility(val),
    });

    if (completed) {
      this.syncVisibility(val);
    }

    return completed;
  }

  componentDidLoad() {
    this.mergedOpen ? this._open() : this._close('programmatic');
    this._componentDidLoadCallback?.();
  }

  disconnectedCallback() {
    this.openAnimation.dispose();
  }

  render() {
    const showHeader = this.title || this.titleSlots || this.description || this.descriptionSlots;
    const showFooter =
      this.showFooter && (this.confirmable || this.cancelable || this.footerSlots || this.footerPrependSlots);

    return (
      <Host class="KsModal">
        {/* FIXME close by escapeKey? */}
        <ks-overlay
          mode="modal"
          open={this.innerOpen}
          captureEscape
          closeByEscape={asObject(this.closeable)?.keyboard !== false}
          onKsRequestClose={this.handleRequestClose}
          deprecatedDisableTopLayer={typeof this.zIndex === 'number'}
          zIndex={this.zIndex}
          data-testid="ks-modal-index-4QLEVG"
        >
          <div
            ref={(el) => (this.overlayRef = el)}
            class={`${prefix}__overlay`}
            ks-open={this.innerOpen || this.mergedOpen ? '' : undefined}
          >
            <div
              class={`${prefix}__backdrop`}
              part="backdrop"
              onClick={this.handleBackdropClick}
              data-testid="ks-modal-index-rWEpeV"
            />

            <div class={prefix} part="base">
              <div
                ref={(el) => (this.wrapperRef = el)}
                class={`${prefix}__wrapper ${prefix}__wrapper--${this.size}`}
                style={{ width: formatCSSLength(this.width) }}
                part="wrapper"
              >
                {showHeader && (
                  <div
                    class={{
                      [`${prefix}__header`]: true,
                      [`${prefix}__header--divider`]: this.showDivider,
                    }}
                    part="header"
                  >
                    <div class={`${prefix}__header-title`}>
                      <div class={`${prefix}__header-title-content`}>
                        <slot name="title">{this.title}</slot>
                      </div>
                      <div class={`${prefix}__header-des`}>
                        <slot name="description">{this.description}</slot>
                      </div>
                    </div>
                  </div>
                )}

                {this.closeable && asObject(this.closeable)?.icon !== false && (
                  <span class={`${prefix}__close`}>
                    <ks-icon-button
                      part="closeIcon"
                      size="md"
                      variant="text"
                      onClick={this.handleCloseIconClick}
                      disabled={this.partProps?.closeIcon?.disabled}
                      data-testid="ks-modal-index-qPKzsp"
                    >
                      <slot name="closeIcon">
                        <KsIconClose />
                      </slot>
                    </ks-icon-button>
                  </span>
                )}

                <div class={`${prefix}__body-wrapper`}>
                  <slot name="body">
                    <div class={`${prefix}__body ks-scrollbar-thin`} part="content">
                      <slot>{t(commonMessages.empty)}</slot>
                    </div>
                  </slot>
                </div>

                {showFooter && (
                  <div
                    class={{
                      [`${prefix}__footer`]: true,
                      [`${prefix}__footer--divider`]: this.showDivider,
                    }}
                    part="footer"
                  >
                    <slot name="footer">
                      <div class={`${prefix}__footer__prepend`}>
                        <slot name="footerPrepend"></slot>
                      </div>
                      <div class={`${prefix}__footer__btns`}>
                        {this.cancelable && (
                          <ks-button
                            part="cancelButton"
                            data-testid="ks-modal-index-sMQyRp"
                            {...(this.partProps?.cancelButton || {})}
                            onClick={this.handleCancelButtonClick}
                          >
                            <slot name="cancelText">{this.cancelText ?? t(commonMessages.cancel)}</slot>
                          </ks-button>
                        )}

                        {this.confirmable && (
                          <ks-button
                            part="confirmButton"
                            variant="primary"
                            data-testid="ks-modal-index-smNjSC"
                            loading={this.confirmLoading}
                            {...(this.partProps?.confirmButton || {})}
                            onClick={this.confirmHandler}
                          >
                            <slot name="confirmText">{this.confirmText ?? t(commonMessages.confirm)}</slot>
                          </ks-button>
                        )}
                      </div>
                    </slot>
                  </div>
                )}
              </div>
            </div>
          </div>
        </ks-overlay>
      </Host>
    );
  }
}
